INSERT INTO products (id, category_id, name, slug, short_description, description, image_url, delivery_method, is_active, available_on_main_store, available_to_resellers, created_at, updated_at) VALUES
  ('prod_canva_pro', 'cat_design', 'Canva Pro EDU / Team Invite', 'canva-pro', '', 'Unlock 100M+ premium stock photos, graphics, videos, audio, and brand kits with zero watermark. Instant invite to licensed team workspace.', '/src/assets/images/product_canva_pro_1791884577674.jpg', 'invite_link', TRUE, TRUE, TRUE, '2026-10-13 09:54:19', '2026-10-13 09:54:19'),
  ('prod_chatgpt_plus', 'cat_ai', 'ChatGPT Plus (GPT-4o & Canvas)', 'chatgpt-plus', '', 'Enjoy high-speed access to OpenAI GPT-4o, Canvas coding editor, image generation, web search, and priority compute without rate bottleneck.', '/src/assets/images/product_chatgpt_plus_1791884578363.jpg', 'manual_credentials', TRUE, TRUE, TRUE, '2026-10-13 09:54:19', '2026-10-13 09:54:19'),
  ('prod_capcut_pro', 'cat_video', 'CapCut Pro Desktop & Mobile', 'capcut-pro', '', 'Professional video editing subscription with cloud space, optical flow slow-mo, vocal isolation, and commercial transitions for TikTok and YouTube creators.', '/src/assets/images/product_capcut_pro_1791884578570.jpg', 'manual_credentials', TRUE, TRUE, TRUE, '2026-10-13 09:54:19', '2026-10-13 09:54:19'),
  ('prod_idm_lifetime', 'cat_utilities', 'Internet Download Manager (IDM)', 'idm-lifetime', '', 'Official digital license key for Internet Download Manager. Seamlessly catches video streams and splits files for maximum bandwidth throughput.', '/src/assets/images/hero_digital_products_1791884577566.jpg', 'instant_license_key', TRUE, TRUE, TRUE, '2026-10-13 09:54:19', '2026-10-13 09:54:19');
